"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[150],{4143(e){e.exports=JSON.parse('{"title":"\uc0c1\ud638\uc791\uc6a9 \ubc94\uc704 \ub354 \uc88b\uac8c \ub9cc\ub4e4\uae30","date":"2024-01-23","coverUrl":null,"html":"<h2 data-notion-block-id=\\"668d4766-6bb0-4066-b308-fb5f79d95b0d\\" id=\\"668d4766-6bb0-4066-b308-fb5f79d95b0d\\">\uc0c1\ud638\uc791\uc6a9 \ubc94\uc704 \ub354 \uc88b\uac8c \ub9cc\ub4e4\uae30</h2><a href=\\"https://ishadeed.com/article/target-size\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/target-size</a><p data-notion-block-id=\\"37dd96c0-d278-4103-a237-6d7a3ed0ae8a\\"><b>\uc2ec\uc724\uc12d</b>: \uc0c1\ud638\uc791\uc6a9\ud558\uc9c0 \uc54a\ub294 UI\uac00 \uc5c6\ub294 \uc6f9 \uc11c\ube44\uc2a4\ub294 \uc5c6\ub2e4\uc2dc\ud53c \ud560 \uc815\ub3c4\ub85c \uc0c1\ud638\uc791\uc6a9\uc740 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4. \uadf8 \uc0c1\ud638\uc791\uc6a9\uc5d0\ub294 \uac00\uc7a5 \uae30\ubcf8\uc801\uc778 Clickable UI\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \ub514\uc790\uc778\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \ucf54\ub4dc\uae4c\uc9c0 \uc801\uc6a9\ud560 \uc218 \uc788\ub294 \ub354 \uc88b\uc740 \uc0c1\ud638\uc791\uc6a9 \ubc94\uc704\uc758 \uc608\uc2dc\ub97c \ubcf4\uc5ec\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub514\uc790\uc774\ub108 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uac1c\ubc1c\uc790\uc5d0\uac8c \uc801\uc6a9\ub418\ub294 \uc608\uc2dc\ub3c4 \ub9ce\uc774 \uc788\uc5b4\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"c8012ee7-6d2d-495c-86f3-2a4bf739f611\\"><b>\ucd5c\uc6d0\ube48</b>: \ud074\ub9ad \uc601\uc5ed\uc758 \uc2dc\uac01\uc801 - \ube44 \uc2dc\uac01\uc801\uc778 \uc601\uc5ed\uae4c\uc9c0 \uad00\ub9ac\ud558\ub294 \uc810\uc774 \uc0c1\ub2f9\ud788 \uc778\uc0c1\uc801\uc778 \uae00\uc774\ub124\uc694. \ub514\uc790\uc778\ub41c \uc791\uc5c5\ubb3c\uc5d0 \uc774\ub7ec\ud55c \uc810\ub4e4\uc774 \uace0\ub824\ub41c \uc0c1\ud0dc\uac00 \uc544\ub2d0 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc8fc\uc5b4\uc9c4 \ub300\ub85c\ub9cc \ub9cc\ub4dc\ub294 \uac83\uc774 \uc544\ub2cc, UX\ub97c \ucc59\uae30\uae30 \uc704\ud574 \ud568\uaed8 \ub450 \ub208 \ud06c\uac8c \ub728\uace0 \ud655\uc778\ud574\uc57c \ud558\ub294 \ubd80\ubd84\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc694. \uc5ec\uae30\uc5d0 UI \ucef4\ud3ec\ub10c\ud2b8\uc758 \uc6f9 \uc811\uadfc\uc131\uae4c\uc9c0 \ucc59\uaca8\uc8fc\ub294 \uac83\uc740 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uc758 \uc5ed\ud560\uc774\uace0 \uc5ed\ub7c9\uc77c\ud14c\uc8e0.</p><h2 data-notion-block-id=\\"5e16c43a-28c7-4497-b656-96ac1c8494c1\\" id=\\"5e16c43a-28c7-4497-b656-96ac1c8494c1\\">ReScript\ub294 TypeScript\uc758 \uafc8\uc744 \uafb8\ub294\uac00</h2><a href=\\"https://rescript-lang.org/blog/release-11-0-0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rescript-lang.org/blog/release-11-0-0</a><p data-notion-block-id=\\"365a88b8-b886-4523-80a7-ffa6bf2aad5e\\"><b>\uc2ec\uc724\uc12d</b>: TypeScript \uc9c0\uc6d0\uc774 \uc6d0\ud65c\ud558\uc9c0 \uc54a\uc73c\uba74 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc4f8 \uc218 \uc5c6\uc744 \uc815\ub3c4\ub85c \uac1c\ubc1c\ud658\uacbd\uc5d0\uc11c JavaScript \ub300\uc2e0 TypeScript\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub9ce\uc544\uc84c\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc TypeScript\ub294 JavaScript\uc758 superset\uc744 \uc9c0\ud5a5\ud558\ub2e4\ubcf4\ub2c8 \uc544\uc26c\uc6b4 \ubd80\ubd84\uc774 \ub9ce\uc2b5\ub2c8\ub2e4. \uadf8\uc5d0 \ube44\ud574 ReScript\ub294 JavaScript\uc758 subset\uc744 \uc9c0\ud5a5\ud558\uace0 Type \uc2dc\uc2a4\ud15c\uc744 \uac15\ud654\uc2dc\ucf1c\uc11c runtime\uc77c \ub54c\uc758 \uc624\ub958\ub97c \uc904\uc600\uc2b5\ub2c8\ub2e4. JS/TS\uc640 \ud638\ud658\uc131\uc744 \ud5a5\uc0c1\ud588\ub2e4\uace0 \ud558\ub2c8 \uc774\ub97c \ud1b5\ud574 \uc0dd\ud0dc\uacc4\uac00 \ud65c\uc131\ud654 \ub418\uc5c8\uc73c\uba74 \uc88b\uaca0\ub124\uc694.</p>"}')}}]);